/* The same finite teacher sentences are prepared before a five-trial block. */
window.LessonAudioPlan=(()=>{
 const rewards=['Aferin!','Harikasın!','Çok güzel!','Bravo!','Süpersin!','Çok iyi yaptın!','Mükemmel!','Başardın!','Ne güzel yaptın!','Çok başarılısın!','Harika bir cevap!','Çok dikkatliydin!','Tebrik ederim!','Şahane!','Çok güzel ilerliyorsun!','Doğru.','Devam ediyoruz.','Muhteşem!','Böyle devam et!','İşte bu, başardın!','Çok güzel söyledin!'];
 const unique=texts=>[...new Set([...texts,...rewards])];
 function object(trials,mode){return unique(trials.flatMap(t=>{const name=t.item.name.toLocaleLowerCase('tr'),verb=mode==='show'?'göster':'eşle';return[`${t.item.accusative} ${verb}.`,...[false,true].map(wrong=>mode==='show'?`${wrong?'Hayır, o değil. ':''}Bu ${name}. Gösterilen resme dokun. ${t.item.accusative} göster.`:`${wrong?'Bu eşleşme olmadı. ':''}Bu ${name}. Yukarıda da ${name} var. Alttaki resmi gösterilen resmin üstüne götür. ${t.item.accusative} eşle.`)];}));}
 function concept(kind,D,mode,trials,stage){return unique(trials.flatMap(t=>{const c=D.color(t.color),name=c.name.toLocaleLowerCase('tr'),verb=mode==='match'?'eşle':'göster';let cue,model;
  if(kind==='color'){cue=mode==='name'?(stage.kind==='region'||t.room?'Bak dikkat! Burası hangi renk? Söyle.':'Bu hangi renk? Söyle.'):`${c.cue} ${verb}.`;model=mode==='match'?`Alttaki kart ${name}. Üstte gösterilen kart da ${name}. Renkleri aynı. Şimdi ${c.cue.toLocaleLowerCase('tr')} eşle.`:`Bak, gösterilen ${t.source.kind==='region'?'bölge':'nesne'} ${name}. Şimdi ${c.cue.toLocaleLowerCase('tr')} göster.`;}
  else if(kind==='length'){cue=mode==='name'?'İşaretli nesne uzun mu, kısa mı? Söyle.':`${name[0].toLocaleUpperCase('tr')+name.slice(1)} olanı ${verb}.`;model=mode==='match'?`Alttaki nesne ${name}. Üstte işaretlenen nesne de ${name}. Şimdi ${name} olanları eşle.`:`Bak, işaretlenen nesne diğerlerinden daha ${name}. Şimdi ${name} olanı göster.`;}
  else if(kind==='age'){cue=mode==='name'?'İşaretli kişi genç mi, yaşlı mı? Söyle.':`${name[0].toLocaleUpperCase('tr')+name.slice(1)} olanı ${verb}.`;model=mode==='match'?`Alttaki kişi ${name}. Üstte işaretlenen kişi de ${name}. Şimdi ${name} olanı eşle.`:`Bak, işaretlenen kişi ${name}. Şimdi ${name} olanı göster.`;}
  else{cue=mode==='name'?D.question:D.instruction(mode);const word=D.concept.name.toLocaleLowerCase('tr'),detail=D.explanation(t.correct);model=D.concept.pair==='time'?`${mode==='match'?'Alttaki ve işaretlenen resimler':'İşaretlenen resim'} ${word} zamanını gösteriyor. ${detail} Şimdi ${D.instruction(mode)}`:D.concept.pair==='position'?`${detail} Şimdi ${D.instruction(mode)}`:mode==='match'?`Alttaki nesne ${word}. Üstte işaretlenen nesne de ${word}. ${detail} Şimdi ${word} olanı eşle.`:`Bak, işaretlenen nesne ${word}. ${detail} Şimdi ${word} olanı göster.`;}
  return[...(D.correction?['uncertain','inappropriate'].flatMap(k=>[true,false].map(retry=>D.correction(t.color,'',k,retry))):[]),cue,`Bu ${name}. Şimdi sen söyle.`,`Bu ${name}.`,`Bu söylediğin sözcük uygun bir sözcük değil. Bu ${name}. Şimdi sen söyle.`,`Bu söylediğin sözcük uygun bir sözcük değil. Bu ${name}.`,...(mode==='name'?[]:[model,`Hayır, bu ${name} değil. `+model])];}));}
 function action(trials,mode){return unique(trials.flatMap(t=>[mode==='name'?'Ne yapıyor? Söyle.':`${t.item.instruction} ${mode==='match'?'eşle':'göster'}.`,`${t.item.model}. Şimdi sen söyle.`,t.item.model+'.',...['',' Şimdi sen söyle.'].flatMap(end=>[`Evet, yaklaştın. ${t.item.model}.`+end,`Bu söylediğin sözcük uygun bir sözcük değil. ${t.item.model}.`+end]),...[false,true].map(wrong=>`${wrong?'Bu eşleşme olmadı. ':''}${t.item.model}. ${mode==='match'?'Alttaki videoyu gösterilen eşiyle eşle.':'Gösterilen eyleme dokun.'}`)]));}
 function naming(trials){return unique(['Bu ne? Söyle.',...trials.flatMap(t=>{const name=t.item.name.toLocaleLowerCase('tr');return[`Evet, yaklaştın. Tam adı ${name}. Şimdi sen söyle.`,`Evet, yaklaştın. Tam adı ${name}.`,`Bu ${name}. Şimdi sen söyle: ${name}.`,`Bu ${name}.`,`Bu ${name}. Şimdi sen söyle.`,`Bu söylediğin sözcük uygun bir sözcük değil. Bu ${name}. Şimdi sen söyle.`,`Bu söylediğin sözcük uygun bir sözcük değil. Bu ${name}.`];})]);}
 function pattern(trials,items){return unique(['Sıraya bakalım. Boş kutuya hangisi gelmeli? Doğru olanı seç.',...trials.flatMap(t=>{const sequence=t.shown.map(k=>items[k].name).join(', '),full=[...t.shown,t.answer],period=full.findIndex((_,i)=>i>0&&full.every((k,p)=>k===full[p%i])),group=full.slice(0,period>0?period:full.length).map(k=>items[k].name).join(', '),detail=period===2?'Bu iki nesne sırayla tekrar ediyor.':`Tekrar eden grup: ${group}. Bu grup aynı sırayla tekrar ediyor.`;return[false,true].map(wrong=>`${wrong?'Hayır, o değil. ':''}Bak, ${sequence}. ${detail} Sırayı devam ettirince buraya ${items[t.answer].name} gelmeli. Şimdi gösterilen seçeneğe bas.`);})]);}
 function events(examples,stories){return unique(['Gösterilen karta dokun.','Hayır, bu kartın yeri farklı. Gösterilen karta dokun.','Resimlere bak. Önce olanı, sonra olanı sırala. Önce olan karta dokun.','Şimdi sıradaki olayı seç.',...rewards.map(r=>`${r} Şimdi sıradaki olayı seç.`),...examples.flatMap(t=>{const s=stories[t.story],sequence=t.indices.map((step,i)=>`${i===0?'Önce':i===t.indices.length-1?'En son':'Sonra'} ${s.steps[step]}`).join(' ');return t.indices.flatMap((_,next)=>[false,true].flatMap(wrong=>[`${wrong?'Hayır, bu kartın yeri farklı. ':''}${sequence} Şimdi gösterilen karta dokun; ${next+1}. yere gelsin.`,`${wrong?'Hayır, bu kartın yeri farklı. ':''}Şimdi gösterilen karta dokun; ${next+1}. yere gelsin.`]));})]);}
 function wh(story){return unique([story.narration,...story.questions.flatMap(q=>[q.text,q.answer,q.evidence,...[' Şimdi sen söyle.',' Şimdi seç.'].flatMap(tail=>[q.evidence+tail,'Bu söylediğin sözcük uygun bir sözcük değil. '+q.evidence+tail]),'Bu söylediğin sözcük uygun bir sözcük değil. '+q.evidence])]);}
 return{object,concept,action,naming,pattern,events,wh,rewards,unique};
})();
